import React, { useState } from "react";
import { motion } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { FiBriefcase, FiBookOpen } from "react-icons/fi";
import { experience } from "../../data/portfolioData";
import "./Experience.css";

export default function Experience() {
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.08 });
  const [filter, setFilter] = useState("all");

  const filtered = filter === "all" ? experience : experience.filter((e) => e.type === filter);

  return (
    <section className="section experience-section" id="experience" ref={ref}>
      <div className="blob blob-2" />
      <div className="experience-container">
        <div className="exp-header">
          <motion.div className="section-label" initial={{ opacity: 0, x: -20 }} animate={inView ? { opacity: 1, x: 0 } : {}} transition={{ duration: 0.5 }}>Journey</motion.div>
          <motion.h2 className="section-title" initial={{ opacity: 0, y: 30 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.6, delay: 0.1 }}>Experience &amp; <span>Education</span></motion.h2>
          <motion.p className="section-subtitle" initial={{ opacity: 0, y: 20 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.5, delay: 0.2 }}>The path that shaped me into who I am today.</motion.p>

          <motion.div className="exp-filters" initial={{ opacity: 0, y: 16 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ delay: 0.3 }}>
            {["all", "work", "education"].map((f) => (
              <button key={f} className={`exp-filter-btn ${filter === f ? "active" : ""}`} onClick={() => setFilter(f)}>
                {f === "all" ? "All" : f === "work" ? "Work" : "Education"}
              </button>
            ))}
          </motion.div>
        </div>

        <div className="timeline">
          <div className="timeline-line" />
          {filtered.map((item, i) => (
            <TimelineItem key={item.id} item={item} index={i} inView={inView} side={i % 2 === 0 ? "left" : "right"} />
          ))}
        </div>
      </div>
    </section>
  );
}

function TimelineItem({ item, index, inView, side }) {
  return (
    <motion.div
      className={`timeline-item ${side}`}
      initial={{ opacity: 0, x: side === "left" ? -40 : 40 }}
      animate={inView ? { opacity: 1, x: 0 } : {}}
      transition={{ duration: 0.6, delay: 0.2 + index * 0.15 }}
    >
      {/* Dot */}
      <div className="timeline-dot">
        <div className="dot-icon">
          {item.type === "work" ? <FiBriefcase size={12} /> : <FiBookOpen size={12} />}
        </div>
      </div>

      {/* Card */}
      <div className="timeline-card glass-card">
        <div className="timeline-card-header">
          <div>
            <span className={`timeline-type-badge ${item.type}`}>
              {item.type === "work" ? "Work" : "Education"}
            </span>
            <h4 className="timeline-title">{item.title}</h4>
            <div className="timeline-company">{item.company}</div>
          </div>
          <div className="timeline-period mono">{item.period}</div>
        </div>
        <p className="timeline-desc">{item.description}</p>
        <div className="timeline-tech">
          {item.tech.map((t) => <span key={t} className="tech-tag">{t}</span>)}
        </div>
      </div>
    </motion.div>
  );
}
