import React from "react";
import { motion } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { FiMapPin, FiMail, FiPhone, FiAward } from "react-icons/fi";
import CountUp from "react-countup";
import { personalInfo, stats, techTags } from "../../data/portfolioData";
import "./About.css";

const fadeUp = {
  hidden: { opacity: 0, y: 40 },
  visible: (i = 0) => ({
    opacity: 1, y: 0,
    transition: { duration: 0.6, delay: i * 0.1, ease: [0.22, 1, 0.36, 1] },
  }),
};

export default function About() {
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.15 });

  return (
    <section className="section about-section" id="about" ref={ref}>
      <div className="blob blob-1" />
      <div className="blob blob-2" />
      <div className="about-container">
        {/* Left */}
        <div className="about-text">
          <motion.div className="section-label" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={0}>About Me</motion.div>
          <motion.h2 className="section-title" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={1}>
            Building the web, <span>one pixel</span> at a time.
          </motion.h2>
          <motion.p className="about-bio" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={2}>{personalInfo.bio}</motion.p>
          <motion.p className="about-bio" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={3}>{personalInfo.bioExtended}</motion.p>
          <motion.div className="about-info-grid" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={4}>
            <InfoItem icon={<FiMapPin />} label="Location" value={personalInfo.location} />
            <InfoItem icon={<FiMail />} label="Email" value={personalInfo.email} />
            <InfoItem icon={<FiPhone />} label="Phone" value={personalInfo.phone} />
            <InfoItem icon={<FiAward />} label="Status" value="Open to Work" highlight />
          </motion.div>
          <motion.div className="tech-tags" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={5}>
            {techTags.map((tag, i) => <span key={i} className="tech-tag">{tag}</span>)}
          </motion.div>
        </div>

        {/* Right */}
        <div className="about-stats-col">
          <div className="stats-grid">
            {stats.map((s, i) => (
              <motion.div key={i} className="stat-card glass-card" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={i + 2}>
                <div className="stat-value">
                  {inView ? <CountUp end={s.value} duration={2.5} suffix={s.suffix} /> : `0${s.suffix}`}
                </div>
                <div className="stat-label">{s.label}</div>
              </motion.div>
            ))}
          </div>
          <motion.div className="code-snippet glass-card" variants={fadeUp} initial="hidden" animate={inView ? "visible" : "hidden"} custom={6}>
            <div className="code-header">
              <span className="code-dot red" /><span className="code-dot yellow" /><span className="code-dot green" />
              <span className="code-filename mono">developer.js</span>
            </div>
            <pre className="code-body mono">{`const Shanmugaraj = {
  role: "Full Stack Dev",
  loves: ["React","UX","Coffee"],
  available: true,
  superpower: () =>
    "Pixel-perfect UI"
};`}</pre>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

function InfoItem({ icon, label, value, highlight }) {
  return (
    <div className="info-item">
      <span className="info-icon">{icon}</span>
      <div>
        <span className="info-label">{label}</span>
        <span className={`info-value ${highlight ? "highlight" : ""}`}>{value}</span>
      </div>
    </div>
  );
}
