import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { FiGithub, FiExternalLink, FiArrowRight } from "react-icons/fi";
import { projects } from "../../data/portfolioData";
import "./Projects.css";

export default function Projects() {
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.08 });
  const [hovered, setHovered] = useState(null);

  const featured = projects.filter((p) => p.featured);
  const others = projects.filter((p) => !p.featured);

  return (
    <section className="section projects-section" id="projects" ref={ref}>
      <div className="blob blob-1" />
      <div className="projects-container">
        {/* Header */}
        <motion.div className="section-label" initial={{ opacity: 0, x: -20 }} animate={inView ? { opacity: 1, x: 0 } : {}} transition={{ duration: 0.5 }}>Selected Work</motion.div>
        <motion.h2 className="section-title" initial={{ opacity: 0, y: 30 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.6, delay: 0.1 }}>Projects that <span>ship.</span></motion.h2>
        <motion.p className="section-subtitle" initial={{ opacity: 0, y: 20 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.5, delay: 0.2 }} style={{ marginBottom: "56px" }}>Real products, real impact.</motion.p>

        {/* Featured Grid */}
        <div className="featured-grid">
          {featured.map((project, i) => (
            <motion.div
              key={project.id}
              className="featured-card glass-card"
              initial={{ opacity: 0, y: 50 }}
              animate={inView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.6, delay: 0.2 + i * 0.15 }}
              onMouseEnter={() => setHovered(project.id)}
              onMouseLeave={() => setHovered(null)}
              style={{ "--card-accent": project.color }}
            >
              <div className="featured-card-visual">
                <div className="project-mockup">
                  <div className="mockup-bar">
                    <span /><span /><span />
                  </div>
                  <div className="mockup-content" style={{ background: `linear-gradient(135deg, ${project.color}18, ${project.color}05)` }}>
                    <div className="mockup-lines">
                      {[80, 60, 90, 45, 70].map((w, j) => (
                        <div key={j} className="mockup-line" style={{ width: `${w}%`, background: j === 0 ? project.color : "var(--border)", opacity: j === 0 ? 0.6 : 0.3 }} />
                      ))}
                    </div>
                  </div>
                </div>
                <div className="card-glow" style={{ background: project.color }} />
              </div>

              <div className="featured-card-body">
                <div className="project-number mono" style={{ color: project.color }}>0{i + 1}</div>
                <h3 className="project-title">{project.title}</h3>
                <p className="project-desc">{project.description}</p>
                <p className="project-long-desc">{project.longDesc}</p>
                <div className="project-tech">
                  {project.tech.map((t) => <span key={t} className="tech-pill" style={{ borderColor: `${project.color}40`, color: project.color }}>{t}</span>)}
                </div>
                <div className="project-links">
                  <a href={project.live} className="project-link-btn primary" style={{ background: project.color }} target="_blank" rel="noopener noreferrer">
                    <FiExternalLink size={14} /> Live Demo
                  </a>
                  <a href={project.github} className="project-link-btn ghost" target="_blank" rel="noopener noreferrer">
                    <FiGithub size={14} /> Code
                  </a>
                </div>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Other Projects */}
        <motion.h3 className="other-title" initial={{ opacity: 0 }} animate={inView ? { opacity: 1 } : {}} transition={{ delay: 0.5 }}>Other Projects</motion.h3>
        <div className="other-grid">
          {others.map((project, i) => (
            <motion.div
              key={project.id}
              className="other-card glass-card"
              initial={{ opacity: 0, y: 30 }}
              animate={inView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.5, delay: 0.5 + i * 0.12 }}
              whileHover={{ y: -6 }}
              style={{ "--card-accent": project.color }}
            >
              <div className="other-card-top">
                <div className="other-card-icon" style={{ color: project.color }}>
                  <FiExternalLink size={20} />
                </div>
                <div className="other-card-links">
                  <a href={project.github} target="_blank" rel="noopener noreferrer"><FiGithub size={16} /></a>
                  <a href={project.live} target="_blank" rel="noopener noreferrer"><FiExternalLink size={16} /></a>
                </div>
              </div>
              <h4 className="other-card-title">{project.title}</h4>
              <p className="other-card-desc">{project.description}</p>
              <div className="other-card-tech">
                {project.tech.slice(0, 3).map((t) => <span key={t} className="tech-tag-sm">{t}</span>)}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
