import React from "react";
import { motion } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { FiCode, FiSmartphone, FiZap, FiGlobe, FiLayers, FiFeather } from "react-icons/fi";
import { services } from "../../data/portfolioData";
import "./Services.css";

const ICONS = { FiCode: <FiCode />, FiSmartphone: <FiSmartphone />, FiZap: <FiZap />, FiGlobe: <FiGlobe />, FiLayers: <FiLayers />, FiFeather: <FiFeather /> };

export default function Services() {
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.08 });

  return (
    <section className="section services-section" id="services" ref={ref}>
      <div className="blob blob-3" />
      <div className="services-container">
        <div className="services-header">
          <motion.div className="section-label" initial={{ opacity: 0, x: -20 }} animate={inView ? { opacity: 1, x: 0 } : {}} transition={{ duration: 0.5 }}>What I Offer</motion.div>
          <motion.h2 className="section-title" initial={{ opacity: 0, y: 30 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.6, delay: 0.1 }}>Services &amp; <span>Capabilities</span></motion.h2>
          <motion.p className="section-subtitle" initial={{ opacity: 0, y: 20 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.5, delay: 0.2 }}>End-to-end frontend solutions — from concept to deployment.</motion.p>
        </div>

        <div className="services-grid">
          {services.map((service, i) => (
            <motion.div
              key={i}
              className="service-card glass-card"
              initial={{ opacity: 0, y: 40 }}
              animate={inView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.55, delay: 0.2 + i * 0.1 }}
              whileHover={{ y: -8 }}
            >
              <div className="service-icon-wrap">
                <div className="service-icon">{ICONS[service.icon]}</div>
                <div className="service-icon-glow" />
              </div>
              <h3 className="service-title">{service.title}</h3>
              <p className="service-desc">{service.description}</p>
              <div className="service-arrow">→</div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
