import React, { useState, useEffect } from "react";
import { Link, useLocation } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { FiSun, FiMoon, FiMenu, FiX } from "react-icons/fi";
import { useScrollProgress, useActiveSection, useTheme } from "../../hooks/usePortfolio";
import "./Navbar.css";

const NAV_LINKS = [
  { label: "About", href: "about" },
  { label: "Skills", href: "skills" },
  { label: "Projects", href: "projects" },
  { label: "Experience", href: "experience" },
  { label: "Services", href: "services" },
  { label: "Contact", href: "contact" },
];

const SECTION_IDS = NAV_LINKS.map((l) => l.href);

export default function Navbar({ isDark, onThemeToggle }) {
  const progress = useScrollProgress();
  const active = useActiveSection(SECTION_IDS);
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const scrollTo = (id) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
    setMenuOpen(false);
  };

  return (
    <>
      {/* Scroll Progress Bar */}
      <div className="scroll-progress" style={{ width: `${progress}%` }} />

      <motion.nav
        className={`navbar-custom ${scrolled ? "scrolled" : ""}`}
        initial={{ y: -80, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
      >
        <div className="navbar-inner">
          {/* Logo */}
          <Link to="/" className="navbar-logo" onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}>
            <span className="logo-bracket">&lt;</span>
            <span className="logo-name">SR</span>
            <span className="logo-bracket">/&gt;</span>
          </Link>

          {/* Desktop Links */}
          <div className="navbar-links">
            {NAV_LINKS.map((link) => (
              <button
                key={link.href}
                className={`nav-link-btn ${active === link.href ? "active" : ""}`}
                onClick={() => scrollTo(link.href)}
              >
                <span className="nav-link-num mono">0{NAV_LINKS.indexOf(link) + 1}.</span>
                {link.label}
              </button>
            ))}
          </div>

          {/* Right Controls */}
          <div className="navbar-controls">
            <button className="theme-toggle" onClick={onThemeToggle} aria-label="Toggle theme">
              <AnimatePresence mode="wait">
                <motion.span
                  key={isDark ? "moon" : "sun"}
                  initial={{ rotate: -90, opacity: 0 }}
                  animate={{ rotate: 0, opacity: 1 }}
                  exit={{ rotate: 90, opacity: 0 }}
                  transition={{ duration: 0.2 }}
                >
                  {isDark ? <FiSun size={18} /> : <FiMoon size={18} />}
                </motion.span>
              </AnimatePresence>
            </button>

            <button className="menu-toggle" onClick={() => setMenuOpen((p) => !p)} aria-label="Menu">
              {menuOpen ? <FiX size={22} /> : <FiMenu size={22} />}
            </button>
          </div>
        </div>

        {/* Mobile Menu */}
        <AnimatePresence>
          {menuOpen && (
            <motion.div
              className="mobile-menu"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3, ease: "easeInOut" }}
            >
              {NAV_LINKS.map((link, i) => (
                <motion.button
                  key={link.href}
                  className={`mobile-nav-btn ${active === link.href ? "active" : ""}`}
                  onClick={() => scrollTo(link.href)}
                  initial={{ x: -20, opacity: 0 }}
                  animate={{ x: 0, opacity: 1 }}
                  transition={{ delay: i * 0.06 }}
                >
                  <span className="mono" style={{ color: "var(--accent)", fontSize: "0.75rem" }}>
                    0{i + 1}.
                  </span>{" "}
                  {link.label}
                </motion.button>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.nav>
    </>
  );
}
