import React, { useState } from "react";
import { motion } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { FiSend, FiMail, FiPhone, FiMapPin, FiGithub, FiLinkedin, FiTwitter } from "react-icons/fi";
import { personalInfo } from "../../data/portfolioData";
import "./Contact.css";

const fadeUp = {
  hidden: { opacity: 0, y: 30 },
  visible: (i = 0) => ({
    opacity: 1, y: 0,
    transition: { duration: 0.55, delay: i * 0.1, ease: [0.22, 1, 0.36, 1] },
  }),
};

export default function Contact() {
  const { ref, inView } = useInView({ threshold: 0.08, triggerOnce: true });
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" });
  const [status, setStatus] = useState(null); // null | 'sending' | 'sent'

  const handleChange = (e) => setForm((p) => ({ ...p, [e.target.name]: e.target.value }));

  const handleSubmit = (e) => {
    e.preventDefault();
    setStatus("sending");
    setTimeout(() => setStatus("sent"), 1800);
  };

  return (
    <section className="section contact-section" id="contact" ref={ref}>
      <div className="blob blob-2" style={{ opacity: 0.05, right: "-100px", bottom: "-100px", left: "auto" }} />
      <div className="section-container">
        <motion.div
          className="section-header"
          variants={fadeUp} initial="hidden"
          animate={inView ? "visible" : "hidden"}
        >
          <p className="section-label">08. Contact</p>
          <h2 className="section-title">Let's <span>connect</span></h2>
          <p className="section-subtitle">
            Have a project in mind or want to say hello? I'm always open to new opportunities.
          </p>
        </motion.div>

        <div className="contact-grid">
          {/* Info */}
          <motion.div
            className="contact-info"
            variants={fadeUp} custom={1}
            initial="hidden" animate={inView ? "visible" : "hidden"}
          >
            <div className="contact-tagline">
              <h3>Ready to build something <span>remarkable?</span></h3>
              <p>
                Whether it's a startup MVP, a design system, or a complex React application —
                let's talk about how I can help.
              </p>
            </div>

            <div className="contact-details">
              <ContactItem icon={<FiMail />} label="Email" value={personalInfo.email} href={`mailto:${personalInfo.email}`} />
              <ContactItem icon={<FiPhone />} label="Phone" value={personalInfo.phone} href={`tel:${personalInfo.phone}`} />
              <ContactItem icon={<FiMapPin />} label="Location" value={personalInfo.location} />
            </div>

            <div className="contact-socials">
              <p className="mono" style={{ fontSize: "0.75rem", color: "var(--text-muted)", marginBottom: "12px" }}>
                // find me online
              </p>
              <div className="social-row">
                <a href={personalInfo.github} target="_blank" rel="noopener noreferrer" className="social-icon-btn">
                  <FiGithub />
                </a>
                <a href={personalInfo.linkedin} target="_blank" rel="noopener noreferrer" className="social-icon-btn">
                  <FiLinkedin />
                </a>
                <a href={personalInfo.twitter} target="_blank" rel="noopener noreferrer" className="social-icon-btn">
                  <FiTwitter />
                </a>
              </div>
            </div>
          </motion.div>

          {/* Form */}
          <motion.div
            className="contact-form-wrap glass-card"
            variants={fadeUp} custom={2}
            initial="hidden" animate={inView ? "visible" : "hidden"}
          >
            {status === "sent" ? (
              <div className="form-success">
                <div className="success-icon">✓</div>
                <h3>Message sent!</h3>
                <p>Thanks for reaching out. I'll get back to you within 24 hours.</p>
                <button className="btn-outline-custom" onClick={() => { setStatus(null); setForm({ name: "", email: "", subject: "", message: "" }); }}>
                  Send another
                </button>
              </div>
            ) : (
              <form className="contact-form" onSubmit={handleSubmit}>
                <div className="form-row">
                  <FormField label="Name" name="name" value={form.name} onChange={handleChange} placeholder="John Doe" required />
                  <FormField label="Email" name="email" type="email" value={form.email} onChange={handleChange} placeholder="john@email.com" required />
                </div>
                <FormField label="Subject" name="subject" value={form.subject} onChange={handleChange} placeholder="Project Inquiry" required />
                <div className="form-group">
                  <label className="form-label">Message</label>
                  <textarea
                    name="message"
                    value={form.message}
                    onChange={handleChange}
                    placeholder="Tell me about your project..."
                    rows={5}
                    className="form-input form-textarea"
                    required
                  />
                </div>
                <button type="submit" className="btn-primary-custom submit-btn" disabled={status === "sending"}>
                  {status === "sending" ? (
                    <><span className="spinner" /> Sending...</>
                  ) : (
                    <><FiSend size={16} /> Send Message</>
                  )}
                </button>
              </form>
            )}
          </motion.div>
        </div>
      </div>
    </section>
  );
}

function FormField({ label, name, type = "text", value, onChange, placeholder, required }) {
  return (
    <div className="form-group">
      <label className="form-label">{label}</label>
      <input
        type={type} name={name} value={value} onChange={onChange}
        placeholder={placeholder} required={required}
        className="form-input"
      />
    </div>
  );
}

function ContactItem({ icon, label, value, href }) {
  const content = (
    <div className="contact-item">
      <div className="contact-item-icon">{icon}</div>
      <div>
        <p className="contact-item-label mono">{label}</p>
        <p className="contact-item-value">{value}</p>
      </div>
    </div>
  );
  return href ? <a href={href} style={{ textDecoration: "none" }}>{content}</a> : content;
}
