import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { skills } from "../../data/portfolioData";
import "./Skills.css";

const TABS = [
  { key: "frontend", label: "Frontend" },
  { key: "backend", label: "Backend" },
  { key: "tools", label: "Tools & DevOps" },
];

export default function Skills() {
  const [active, setActive] = useState("frontend");
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.1 });

  return (
    <section className="section skills-section" id="skills" ref={ref}>
      <div className="blob blob-3" />
      <div className="skills-container">
        <div className="skills-header">
          <motion.div className="section-label" initial={{ opacity: 0, x: -20 }} animate={inView ? { opacity: 1, x: 0 } : {}} transition={{ duration: 0.5 }}>Expertise</motion.div>
          <motion.h2 className="section-title" initial={{ opacity: 0, y: 30 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.6, delay: 0.1 }}>My <span>Skill</span> Set</motion.h2>
          <motion.p className="section-subtitle" initial={{ opacity: 0, y: 20 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.5, delay: 0.2 }}>Constantly evolving, always learning — here's where I shine.</motion.p>
        </div>

        <motion.div className="skill-tabs" initial={{ opacity: 0, y: 20 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ duration: 0.5, delay: 0.3 }}>
          {TABS.map((tab) => (
            <button key={tab.key} className={`skill-tab ${active === tab.key ? "active" : ""}`} onClick={() => setActive(tab.key)}>
              {tab.label}
              {active === tab.key && <motion.div className="tab-underline" layoutId="tabUnderline" />}
            </button>
          ))}
        </motion.div>

        <AnimatePresence mode="wait">
          <motion.div key={active} className="skills-grid" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.35 }}>
            {skills[active].map((skill, i) => (
              <SkillBar key={skill.name} skill={skill} index={i} inView={inView} />
            ))}
          </motion.div>
        </AnimatePresence>

        <motion.div className="skill-icons-row" initial={{ opacity: 0 }} animate={inView ? { opacity: 1 } : {}} transition={{ delay: 0.6 }}>
          {["HTML", "Css", "JavaScript", "React", "Java", "Spring boot", "MySQL"].map((name, i) => (
            <motion.div key={name} className="skill-icon-chip" whileHover={{ scale: 1.08, y: -4 }} initial={{ opacity: 0, y: 20 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ delay: 0.5 + i * 0.06 }}>
              {name}
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
}

function SkillBar({ skill, index, inView }) {
  return (
    <motion.div className="skill-bar-wrap" initial={{ opacity: 0, x: -20 }} animate={inView ? { opacity: 1, x: 0 } : {}} transition={{ duration: 0.5, delay: index * 0.08 }}>
      <div className="skill-bar-header">
        <span className="skill-name">{skill.name}</span>
        <span className="skill-level mono">{skill.level}%</span>
      </div>
      <div className="skill-bar-track">
        <motion.div className="skill-bar-fill" initial={{ width: 0 }} animate={inView ? { width: `${skill.level}%` } : { width: 0 }} transition={{ duration: 1.2, delay: 0.3 + index * 0.1, ease: [0.22, 1, 0.36, 1] }}>
          <div className="skill-bar-shine" />
        </motion.div>
      </div>
    </motion.div>
  );
}
