import React from "react";
import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";
import { AnimatePresence } from "framer-motion";
import Navbar from "./components/Navbar/Navbar";
import Footer from "./components/Footer/Footer";
import Home from "./pages/Home";
import NotFound from "./pages/NotFound";
import { BackToTop, CustomCursor } from "./components/UI/UIElements";
import { useTheme } from "./hooks/usePortfolio";
import "bootstrap/dist/css/bootstrap.min.css";
import "./styles/global.css";

function AnimatedRoutes({ isDark, onThemeToggle }) {
  const location = useLocation();

  return (
    <>
      <Navbar isDark={isDark} onThemeToggle={onThemeToggle} />
      <AnimatePresence mode="wait">
        <Routes location={location} key={location.pathname}>
          <Route path="/" element={<Home />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </AnimatePresence>
      <Footer />
    </>
  );
}

export default function App() {
  const { isDark, toggle } = useTheme();

  return (
    <BrowserRouter>
      <CustomCursor />
      <BackToTop />
      <AnimatedRoutes isDark={isDark} onThemeToggle={toggle} />
    </BrowserRouter>
  );
}
