import { useState, useEffect, useRef } from "react";

export function useScrollProgress() {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    const update = () => {
      const scrollTop = window.scrollY;
      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
      setProgress(docHeight > 0 ? (scrollTop / docHeight) * 100 : 0);
    };
    window.addEventListener("scroll", update, { passive: true });
    return () => window.removeEventListener("scroll", update);
  }, []);
  return progress;
}

export function useActiveSection(sectionIds) {
  const [active, setActive] = useState("");
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) setActive(e.target.id);
        });
      },
      { rootMargin: "-40% 0px -55% 0px" }
    );
    sectionIds.forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, [sectionIds]);
  return active;
}

export function useTheme() {
  const [isDark, setIsDark] = useState(true);
  useEffect(() => {
    document.documentElement.setAttribute("data-theme", isDark ? "dark" : "light");
  }, [isDark]);
  return { isDark, toggle: () => setIsDark((p) => !p) };
}

export function useCustomCursor() {
  const cursorRef = useRef(null);
  const followerRef = useRef(null);
  useEffect(() => {
    let mouse = { x: 0, y: 0 };
    let follower = { x: 0, y: 0 };
    let raf;
    const move = (e) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
      if (cursorRef.current) {
        cursorRef.current.style.transform = `translate(${mouse.x - 6}px, ${mouse.y - 6}px)`;
      }
    };
    const animate = () => {
      follower.x += (mouse.x - follower.x) * 0.12;
      follower.y += (mouse.y - follower.y) * 0.12;
      if (followerRef.current) {
        followerRef.current.style.transform = `translate(${follower.x - 20}px, ${follower.y - 20}px)`;
      }
      raf = requestAnimationFrame(animate);
    };
    window.addEventListener("mousemove", move, { passive: true });
    raf = requestAnimationFrame(animate);
    return () => {
      window.removeEventListener("mousemove", move);
      cancelAnimationFrame(raf);
    };
  }, []);
  return { cursorRef, followerRef };
}
